import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $[r,s]$ denote the least common multiple of positive integers $r$ and $s$. Find the number of ordered quadruples $(a,b,c,d)$ of positive integers for which $[a,b] = {l1}$, $[b,c] = {l2}$, $[c,d] = {l3}$, and $[d,a] = {l4}$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
primes = rng.sample([2, 3, 5, 7, 11, 13, 17, 19], 3)
primes.sort()

exponent_vectors = []

# Pattern 1: (k, k, k, k)
k = rng.randint(1, 3)
exponent_vectors.append([k, k, k, k])

# Pattern 2: (m, m, m+d, m+d) rotated
m = rng.randint(1, 2)
d = rng.randint(1, 2)
base_p2 = (m, m, m + d, m + d)
rot = rng.randint(0, 3)
p2_exps = list(base_p2[rot:] + base_p2[:rot])
exponent_vectors.append(p2_exps)

# Pattern 3: (j, j+e, j+e, j+e) rotated
j = rng.randint(1, 2)
e = rng.randint(1, 2)
base_p3 = (j, j + e, j + e, j + e)
rot = rng.randint(0, 3)
p3_exps = list(base_p3[rot:] + base_p3[:rot])
exponent_vectors.append(p3_exps)

# Check for duplicate L_i vectors and retry if found
# Transpose to get vectors for L1, L2, L3, L4
l_vectors = list(zip(*exponent_vectors))
if len(set(l_vectors)) != 4:
    return generator(rng) # Retry

Ls = [1, 1, 1, 1]
for i in range(4):
    for prime_idx, prime in enumerate(primes):
        Ls[i] *= prime ** exponent_vectors[prime_idx][i]

# Check if numbers are too large
if any(l > 100000 for l in Ls):
    return generator(rng) # Retry

return {
    'l1': Ls[0],
    'l2': Ls[1],
    'l3': Ls[2],
    'l4': Ls[3]
}

    def verifier(assign):
l = [assign['l1'], assign['l2'], assign['l3'], assign['l4']]

if any(val <= 0 for val in l):
    return False, None # Inputs must be positive

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

prime_factors = set()
l_factors = []
for val in l:
    factors = get_prime_factorization(val)
    l_factors.append(factors)
    for p in factors:
        prime_factors.add(p)

total_solutions = 1
for p in sorted(list(prime_factors)):
    k = tuple(factors.get(p, 0) for factors in l_factors)
    k1, k2, k3, k4 = k

    # Check for strict local maximum, which yields 0 solutions
    if (k1 > k2 and k1 > k4) or \
       (k2 > k1 and k2 > k3) or \
       (k3 > k2 and k3 > k4) or \
       (k4 > k3 and k4 > k1):
        total_solutions = 0
        break

    counts = {}
    for val in k:
        counts[val] = counts.get(val, 0) + 1

    unique_exponents = sorted(counts.keys())

    sols_p = 0
    if len(unique_exponents) == 1: # Case (k,k,k,k)
        val_k = unique_exponents[0]
        sols_p = 2 * val_k**2 + 4 * val_k + 1
    elif len(unique_exponents) == 2:
        k_small, k_large = unique_exponents
        if counts[k_large] == 3: # Case (k, K, K, K)
            sols_p = 2 * k_small + 1
        elif counts[k_large] == 2 and counts[k_small] == 2:
            # Case (k, k, K, K) or (k, K, k, K)
            # Find position of small values
            small_indices = {i for i, v in enumerate(k) if v == k_small}
            if small_indices == {0, 1} or small_indices == {1, 2} or small_indices == {2, 3} or small_indices == {3, 0}:
                # Adjacent small values: (k,k,K,K)
                sols_p = k_small**2 + 3 * k_small + 1
            else: # Diagonal small values: (k,K,k,K)
                sols_p = 0
        else:
            # Should not be reached by generator
            return False, None
    else:
        # Should not be reached by generator
        return False, None

    total_solutions *= sols_p

return True, total_solutions


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

